head.script:
    imports("uiplugin.popup");    
    scwin.trigger1_onclick = function(e) {
        var options = {
            id : "popup1",
            type : "window",    
            useIFrame : true,
            popupName : "PopupName",
            style : "", 
            top: "50px",
            left: "50px",
            width: "800px",
            height: "500px",

            modal : true, 
            title : true,

            openAction: "scwin.openFunc",
            closeAction: "scwin.closeFunc",
            buttonInfo: {
                alignment: "left",
                buttons: [{
                    value: "button_0",
                    clickAction: "scwin.clickFunc_0",
                    className: ""
                }, {
                    value: "button_1",
                    clickAction: "scwin.clickFunc_1"
                }, {
                    value: "button_2",
                    clickAction: "scwin.clickFunc_2"
                }, {
                    value: "button_3",
                    clickAction: "scwin.clickFunc_3"
                }, {
                    value: "button_4_size",
                    clickAction: "scwin.clickFunc_4"
                }]
            }
        };
        $p.openPopup("", options);
    };
    scwin.trigger2_onclick = function(e) {
        windowContainer1.createWindow({
            "title" : "accordion", 
            "src" : "generator_accordion.xml", 
            "windowId" : "window1", 
            "frameMode" : "wframe",
            "openAction" : "existWindow",
            buttonInfo: {
                alignment: "left",
                buttons: [{
                    value: "button_0",
                    clickAction: "scwin.clickFunc_0",
                    className: "button_0"
                }, {
                    value: "button_1",
                    clickAction: "scwin.clickFunc_1",
                    className: "button_1"
                }, {
                    value: "button_2",
                    clickAction: "scwin.clickFunc_2",
                    className: "button_2"
                }, {
                    value: "button_3",
                    clickAction: "scwin.clickFunc_3",
                    className: "button_3"
                }, {
                    value: "button_4_size",
                    clickAction: "scwin.clickFunc_4",
                    className: "button_4"
                }]
            }
        });
    };
	scwin.onpageload = function() {
	};

	scwin.onpageunload = function() {

	};

    scwin.openFunc = function(obj) {
        alert(" [ACTION] YOU OPENED POPUP ");
    }
    scwin.closeFunc = function(obj) {
        alert(" [ACTION] YOU CLOSED POPUP ");
        return true;
    }
    scwin.clickFunc_0 = function(obj) {
        alert(" [ACTION] YOU CLICKED BUTTON 0 ");
    }
    scwin.clickFunc_1 = function(obj) {
        alert(" [ACTION] YOU CLICKED BUTTON 1 ");
    }
    scwin.clickFunc_2 = function(obj) {
        alert(" [ACTION] YOU CLICKED BUTTON 2 ");
    }
    scwin.clickFunc_3 = function(obj) {
        alert(" [ACTION] YOU CLICKED BUTTON 3 ");
    }
    scwin.clickFunc_4 = function(obj) {
        alert(" [ACTION] YOU CLICKED BUTTON 4 ");
    }

	scwin.checkVal1 = function(){
		return WebSquare.wUnit.getJq('#popup1_header_button_0_content').offset().left > 220;
	} 	
	scwin.unitTest = function(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "1000");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
